      const theme=REWARD_THEMES.find(t=>t.id===selected);
      const pool=theme.items.map((names,i)=>({themeImage:`/assets/themes/${selected}.png`,frame:theme.frames[i],sprite:i,name:names[column],text:copy.found}));
